import unittest

from xcstool import jsonfmt

XCODE_TEXT = """{
  "sourceLanguage" : "en",
  "strings" : {
    "%@\\/%@ \\"quoted\\"\\n" : {

    },
    "Empty list" : {
      "items" : [

      ],
      "list" : [
        1,
        true
      ]
    },
    "Ünïcödé / 日本" : {
      "isCommentAutoGenerated" : true,
      "localizations" : {
        "ja" : {
          "stringUnit" : {
            "state" : "translated",
            "value" : "日本語 / テキスト"
          }
        }
      },
      "number" : 1.50,
      "shouldTranslate" : false
    }
  },
  "version" : "1.0"
}"""


class JsonFormatTests(unittest.TestCase):
    def test_round_trip_is_byte_identical(self):
        # "\\/" is a valid escape that is normalized; everything else is kept.
        self.assertIn("\\/", XCODE_TEXT)
        text = XCODE_TEXT.replace("\\/", "/")
        self.assertEqual(jsonfmt.dumps(jsonfmt.loads(text)), text)

    def test_formatting_details(self):
        text = jsonfmt.dumps({"a": {}, "b": 'x/y é\n\t"', "c": [], "d": None})
        self.assertEqual(
            text,
            '{\n  "a" : {\n\n  },\n  "b" : "x/y é\\n\\t\\"",\n  "c" : [\n\n  ],\n  "d" : null\n}',
        )
        self.assertFalse(text.endswith("\n"))

    def test_numbers_keep_their_text(self):
        value = jsonfmt.loads('{"a" : 1.50, "b" : 10, "c" : 1e3}')
        self.assertEqual(jsonfmt.dumps(value), '{\n  "a" : 1.50,\n  "b" : 10,\n  "c" : 1e3\n}')

    def test_key_order_is_preserved(self):
        value = jsonfmt.loads('{"z" : 1, "a" : 2, "m" : 3}')
        self.assertEqual(list(value), ["z", "a", "m"])

    def test_lone_surrogate_stays_escaped(self):
        text = jsonfmt.dumps(jsonfmt.loads('"a\\ud800b"'))
        self.assertEqual(text, '"a\\ud800b"')
        text.encode("utf-8")


if __name__ == "__main__":
    unittest.main()
